vec2 curl(vec2 p,float t){
    float e=0.01;
    float nx0=fbm(p+vec2(0,e)+t*0.07);
    float nx1=fbm(p-vec2(0,e)+t*0.07);
    float ny0=fbm(p+vec2(e,0)+t*0.07);
    float ny1=fbm(p-vec2(e,0)+t*0.07);
    return vec2(nx0-nx1,-(ny0-ny1))/(2.0*e);
}
