    float grain=fbm(p*7.0)*0.13+0.07;
    vec3 asp=vec3(grain*0.84,grain*0.87,grain*0.91);
    vec3 col=mix(asp,iriCol*0.62+vec3(0.02,0.01,0.03),oilMask);
